mapper.select:
SELECT g.id, g.group_code, g.group_name, g.avatar, g.description, g.owner_id, g.join_mode, g.status
FROM cf_group g


    (
    g.owner_id = #{userId}

    OR EXISTS (
    SELECT 1
    FROM cf_group_member gm
    WHERE gm.group_id = g.id
    AND gm.user_id = #{userId}
    )
    )


        AND g.group_name LIKE CONCAT('%', #{groupName}, '%')




ORDER BY g.created_at DESC
